const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laSerena = ee.Geometry.Point([-71.2520, -29.9045]); // Approximate center of La Serena, Chile
  const startDate = '2022-07-01';
  const endDate = '2022-07-31';
  const rainfallThresholdCm = 6; // cm
  const rainfallThresholdMm = rainfallThresholdCm * 10; // Convert cm to mm for comparison

  // 2. Data Acquisition
  // Using CHIRPS Daily precipitation data (mm/day)
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
                   .filterDate(startDate, endDate)
                   .filterBounds(laSerena);

  // Check if the collection is empty
  const collectionSize = await chirps.size().getInfo();
  if (collectionSize === 0) {
    console.log("No CHIRPS daily precipitation data found for July 2022 in La Serena.");
    console.log("C1");
    return;
  }
  console.log(`CHIRPS images found for July 2022: ${collectionSize}`);

  // 3. Processing: Sum daily precipitation for the month
  // The 'precipitation' band is in mm/day. Summing all images gives total mm for the period.
  const totalMonthlyPrecipitation = chirps.select('precipitation').sum();

  // Calculate the mean precipitation over the defined geometry
  // Use a scale of 5000m to avoid timeout issues with global datasets
  const precipResult = await totalMonthlyPrecipitation.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: laSerena,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // 4. Validation & Final Answer
  if (precipResult === null || isNaN(precipResult)) {
    console.log("Calculation Failure: Could not retrieve precipitation value.");
    console.log("C3");
    return;
  }

  // Convert total precipitation from mm to cm
  const totalRainfallCm = precipResult / 10; // mm to cm

  console.log(`July 2022 Total Rainfall in La Serena: ${totalRainfallCm.toFixed(2)} cm`);
  console.log(`Threshold: ${rainfallThresholdCm} cm`);

  if (totalRainfallCm >= rainfallThresholdCm) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
